23	
24	// ReceiptConfirmation 是接收方登记回执后得到的确认。
25	// 只含交换标识、当前状态、回执结果与登记时间，不含任何受保护内容；
26	// 授权失效或患者停用后登记回执也只返回该确认。
27	type ReceiptConfirmation struct {
28		ExchangeID   ID
29		Status       string
30		Outcome      string
31		RegisteredAt time.Time
32	}
33	
34	// CreateExchange 由内部使用者把一条当前有效授权覆盖的已生效记录集合打包给
35	// 指定接收方。
36	//
37	// 参数：患者、接收方、绑定授权、记录标识集合与非空请求号。记录必须属于该
38	// 患者且已经生效；每条记录都必须被绑定的那一条授权覆盖——整类范围按记录的
39	// 就诊+类别覆盖，限定范围只覆盖明确选中的记录，不能借用同一接收方的其他
40	// 授权补足。授权必须属于该患者与接收方且在当前时间有效。空集合、空白请求号、
41	// 夹带无效 UTF-8 字节的请求号、不存在或跨患者的引用、夹带草稿、记录不被绑定
42	// 授权覆盖、授权不符一律拒绝，不留下交换或审计，也不占用请求号。患者停用后不能新建交换。
43	//
44	// 成功后包内容固化为创建时各记录的当前生效版本（重复记录标识合并），并计算
45	// 稳定摘要，状态为待回执；交换与审计事件在同一次原子落盘中保留。此后记录被
46	// 更正或有新版本、新增记录都不会改写已创建的包。
47	//
48	// 请求号按发起的内部使用者区分：同一使用者以相同请求号携带相同患者、接收方、
49	// 授权与记录集合（顺序不限）重试时，返回原交换及其现有状态，不重新取内容、
50	// 不新增审计；其他参数变化返回 ErrConflict。首次失败不占用请求号。
51	// 命中已保存交换的重试只是读取既有结果、不产生任何状态变更，因此不再落盘：
52	// 即使本地保存条件当前不可用，重试也成功返回正式保存的那份交换。
53	func (s *Store) CreateExchange(actor Actor, patientID ID, receiverID, authorizationID ID, recordIDs []ID, requestID string) (Exchange, error) {
54		if !actor.valid() || !actor.IsInternal() {
55			return Exchange{}, ErrAccessDenied
56		}
57		if patientID == "" {
58			return Exchange{}, fmt.Errorf("%w: patient id is required", ErrInvalidArgument)
59		}
60		if strings.TrimSpace(receiverID) == "" {
61			return Exchange{}, fmt.Errorf("%w: receiver id is required", ErrInvalidArgument)
62		}
63		if strings.TrimSpace(authorizationID) == "" {
64			return Exchange{}, fmt.Errorf("%w: authorization id is required", ErrInvalidArgument)
65		}
66		if strings.TrimSpace(requestID) == "" {
67			return Exchange{}, fmt.Errorf("%w: request id is required", ErrInvalidArgument)
68		}
69		// 请求号必须是完整合法的 UTF-8：本地快照以 JSON 落盘，encoding/json
70		// 会把无效字节静默替换为 U+FFFD——若放行，重开后保存的请求号与提交时
71		// 不同，原请求号重试找不到原交换，还可能与另一份明确含 U+FFFD 的合法
72		// 请求号撞成同一个。因此夹带任何无效字节或不完整多字节字符的请求号
73		// 一律拒绝，绝不靠替换、截断或跳过坏字节继续创建；用户明确输入的合法
74		// U+FFFD 字符本身是合法 UTF-8，不受此限制。
75		if !utf8.ValidString(requestID) {
76			return Exchange{}, fmt.Errorf("%w: request id must be valid UTF-8", ErrInvalidArgument)
77		}
78		if len(recordIDs) == 0 {
79			return Exchange{}, fmt.Errorf("%w: record id set must not be empty", ErrInvalidArgument)
80		}
81		for _, rid := range recordIDs {
82			if strings.TrimSpace(rid) == "" {
83				return Exchange{}, fmt.Errorf("%w: record id must not be blank", ErrInvalidArgument)
84			}
85		}
86		wanted := uniqueSortedIDs(recordIDs)
87	
88		var result Exchange
89		err := s.mutate(func(snap *snapshot) error {
90			// 幂等检索优先：同一使用者的同一请求号无论当前患者/授权状态如何，
91			// 都只返回原结果（重试不是新建）。
92			if existing := findExchangeByRequest(snap, actor.ID, requestID); existing != nil {
93				if !sameExchangeRequest(existing, patientID, receiverID, authorizationID, wanted) {
94					return fmt.Errorf("%w: request id %q already used with different parameters", ErrConflict, requestID)
95				}
96				result = *existing
97				if existing.Receipt != nil {
98					r := *existing.Receipt
99					result.Receipt = &r
100				}
101				result.Package.Records = append([]PackagedRecord(nil), existing.Package.Records...)
102				// 命中已保存的交换：没有任何状态变更，不落盘——即使本地保存
103				// 条件当前不可用，重试也必须成功返回原交换。
104				return errUnchanged
105			}
106	
107			// 首次创建：患者必须存在且未停用。
108			if _, err := requireActivePatient(snap, patientID); err != nil {
109				return err
110			}
111	
112			// 绑定授权必须存在、属于该患者与接收方、当前有效。
113			a := snap.Authorizations[authorizationID]
114			if a == nil {
115				return fmt.Errorf("%w: authorization %q", ErrNotFound, authorizationID)
116			}
117			if a.PatientID != patientID {
118				return fmt.Errorf("%w: authorization %q belongs to patient %q, not %q",
119					ErrMismatchedPatient, authorizationID, a.PatientID, patientID)
120			}
121			if a.ReceiverID != receiverID {
122				return fmt.Errorf("%w: authorization %q is bound to receiver %q, not %q",
123					ErrInvalidArgument, authorizationID, a.ReceiverID, receiverID)
124			}
125			now := s.now()
126			if !a.ActiveAt(now) {
127				// 未开始、已到期或已撤回：没有覆盖此次打包的有效授权。
128				return fmt.Errorf("%w: authorization %q is not active", ErrAccessDenied, authorizationID)
129			}
130	
131			// 覆盖只由绑定的这一条授权解释：整类范围或限定范围，与接收方查阅
132			// 共用同一套判定（grantCoverage）。同一接收方的其他授权不并入其中，
133			// 因此不能借用其他授权补足覆盖。
134			coverage := newGrantCoverage()
135			coverage.add(a)
136	
137			// 逐记录固化当前生效版本；重复标识已合并，按记录标识排序保证确定性。
138			pkg := Package{PatientID: patientID, ReceiverID: receiverID}
139			for _, rid := range wanted {
140				r := snap.Records[rid]
141				if r == nil {
142					return fmt.Errorf("%w: record %q", ErrNotFound, rid)
143				}
144				if r.PatientID != patientID {
145					return fmt.Errorf("%w: record %q belongs to patient %q, not %q",
146						ErrMismatchedPatient, rid, r.PatientID, patientID)
147				}
148				if r.CurrentVersionID == "" {
149					return fmt.Errorf("%w: record %q has no effective version; activate its draft first",
150						ErrInvalidArgument, rid)
151				}
152				v := snap.Versions[r.CurrentVersionID]
153				if v == nil {
154					return fmt.Errorf("%w: current version %q of record %q", ErrNotFound, r.CurrentVersionID, rid)
155				}
156				// 每条记录都必须被绑定授权自身覆盖：整类范围或限定范围。
157				// 夹带一条未覆盖记录即整包拒绝，不保存其中合法部分。
158				if !coverage.coversRecord(r) {
159					return fmt.Errorf("%w: record %q (encounter %q, category %q) is not covered by authorization %q",
160						ErrAccessDenied, rid, r.EncounterID, r.Category, authorizationID)
161				}
162				pkg.Records = append(pkg.Records, PackagedRecord{
163					EncounterID: r.EncounterID,
164					Category:    r.Category,
165					RecordID:    r.ID,
166					VersionID:   v.ID,
167					Version:     v.Number,
168					EffectiveAt: v.CreatedAt,
169					Content:     v.Content,
170				})
171			}
172	
173			x := &Exchange{
174				ID:              newID("exch"),
175				PatientID:       patientID,
176				ReceiverID:      receiverID,
177				AuthorizationID: authorizationID,
178				RequestID:       requestID,
179				CreatorID:       actor.ID,
180				Status:          ExchangePending,
181				Digest:          packageDigest(pkg),
182				Package:         pkg,
183				CreatedAt:       now,
184			}
185			snap.Exchanges[x.ID] = x
186			s.addAudit(snap, patientID, actor, ActionExchanged, "exchange", x.ID, now)
187			result = *x
188			result.Package.Records = append([]PackagedRecord(nil), x.Package.Records...)
189			return nil
190		})
191		return result, err
192	}
193	
194	// FetchPackage 供指定接收方凭交换标识取包。
195	//
196	// 每次取包都重新检查绑定授权与患者状态：授权必须仍是创建时绑定的那一条且
197	// 已开始、未到期、未撤回，患者档案必须未停用；其他有效授权不能替代绑定授权。
198	// 是否允许取包按“本次核对时间”判断：请求发出后若因等待同一存储上的其他操作
199	// 而排队，以等待结束、真正开始核对本次取包权限的时刻为准（进入临界区后才
200	// 取样，与接收方 Read 的时间含义一致），提前发出的请求不会延长授权有效期；
201	// 时间窗仍是半开区间 [开始, 截止)，恰好到达截止时刻即失效。授权未开始、
202	// 到期、撤回或患者停用后返回 ErrAccessDenied，交付结果为空，不返回包内容、
203	// 摘要、记录标识或交换状态。
204	// 其他接收方、内部使用者以及不存在的交换统一拒绝，不泄露交换是否存在。
205	//
206	// 成功时返回交换创建时固化的包及其摘要与当前状态；此后记录被更正也不会
207	// 重新打包，包内版本与内容仍以创建时保存的为准。
208	func (s *Store) FetchPackage(actor Actor, exchangeID ID) (PackageDelivery, error) {
209		if !actor.valid() || actor.Kind != "receiver" {
210			return PackageDelivery{}, ErrAccessDenied
211		}
212		if strings.TrimSpace(exchangeID) == "" {
213			return PackageDelivery{}, fmt.Errorf("%w: exchange id is required", ErrInvalidArgument)
214		}
215	
216		var out PackageDelivery
217		err := s.view(func(snap *snapshot) error {
218			// 核对时刻在进入临界区、真正开始核对本次取包权限时才取样：请求发出后
219			// 若因等待其他操作而排队，等待时间不能延长绑定授权的有效判断——
220			// 是否可取一律按这同一时刻判断，与 Read 的时间含义一致。
221			now := s.now()
222			x := snap.Exchanges[exchangeID]
223			if x == nil || x.ReceiverID != actor.ID {
224				// 不存在或属于其他接收方：统一拒绝，不泄露存在性。
225				return ErrAccessDenied
226			}
227			p := snap.Patients[x.PatientID]
228			if p == nil || p.Deactivated {
229				return ErrAccessDenied
230			}
231			// 必须仍是绑定的那条授权（同一患者与接收方）；其他有效授权不能替代。
232			a := snap.Authorizations[x.AuthorizationID]
233			if a == nil || a.PatientID != x.PatientID || a.ReceiverID != actor.ID || !a.ActiveAt(now) {
234				return ErrAccessDenied
235			}
236			out = PackageDelivery{
237				ExchangeID: x.ID,
238				Status:     x.Status,
239				Digest:     x.Digest,
240				CreatedAt:  x.CreatedAt,
241				Package:    clonePackage(x.Package),
242			}
243			return nil
244		})
245		return out, err
246	}
247	
248	// SubmitReceipt 供指定接收方对一份包登记回执：提供交换标识、取包时得到的
249	// 包摘要、接受或拒绝的结果及原因。
250	//
251	// 非法结果、拒绝时原因为空白返回 ErrInvalidArgument。拒绝原因还必须是完整
252	// 合法的 UTF-8：本地快照以 JSON 落盘，encoding/json 会把无效字节静默替换为
253	// U+FFFD——若放行，当次内部查询还能看到提交的原字节，关闭重开后原因却已被
254	// 改写，原样原因重交也会因此被判为原因不同。因此夹带任何无效字节或不完整
255	// 多字节字符的拒绝原因一律拒绝，绝不靠替换、截断或跳过坏字节继续登记；
256	// 用户明确输入的合法 U+FFFD 字符本身是合法 UTF-8，不受此限制。只有指定
257	// 接收方且摘要吻合，才能把交换从待回执变为已接受或已拒绝；摘要不符返回
258	// ErrConflict，状态不变。相同回执（结果与原因均相同）重交只是确认已保存
259	// 的那份回执：返回原确认（登记时间保持首次成功登记时的值），不新增审计、
260	// 不改写已保存数据，也不触发落盘——即使本地保存条件当前不可用，重交仍
261	// 成功返回原确认；结果或原因改变返回 ErrConflict，与当前能否保存无关。
262	// 其他身份不能代交，不存在的交换统一拒绝。接受回执不保存原因：传入的原因
263	// （即使夹带无效字节）一律忽略为空，既不会因此拒绝接受，也不参与重交判定。
264	//
265	// 授权失效或患者停用后仍允许登记此前包的回执，但响应只返回确认状态，
266	// 不提供任何受保护内容。
267	func (s *Store) SubmitReceipt(actor Actor, exchangeID ID, digest, outcome, reason string) (ReceiptConfirmation, error) {
268		if !actor.valid() || actor.Kind != "receiver" {
269			return ReceiptConfirmation{}, ErrAccessDenied
270		}
271		if strings.TrimSpace(exchangeID) == "" {
272			return ReceiptConfirmation{}, fmt.Errorf("%w: exchange id is required", ErrInvalidArgument)
273		}
274		if outcome != ReceiptAccepted && outcome != ReceiptRejected {
275			return ReceiptConfirmation{}, fmt.Errorf("%w: outcome must be %q or %q", ErrInvalidArgument, ReceiptAccepted, ReceiptRejected)
276		}
277		if outcome == ReceiptRejected {
278			if strings.TrimSpace(reason) == "" {
279				return ReceiptConfirmation{}, fmt.Errorf("%w: rejection reason is required", ErrInvalidArgument)
280			}
281			// 拒绝原因会随回执原样落盘，必须是完整合法的 UTF-8：坏字节位于开头、
282			// 中间、结尾，或最后一个多字节字符没有写完整，都在此拒绝，不能让 JSON
283			// 落盘把原因替换成 U+FFFD，导致重开后的原因与接收方提交时不同。
284			if !utf8.ValidString(reason) {
285				return ReceiptConfirmation{}, fmt.Errorf("%w: rejection reason must be valid UTF-8", ErrInvalidArgument)
286			}
287		} else {
288			// 接受不携带原因；统一归一化，保证重复提交判定稳定。被忽略的原因
289			// 即使夹带无效字节也不影响接受登记。
290			reason = ""
291		}
292	
293		var conf ReceiptConfirmation
294		err := s.mutate(func(snap *snapshot) error {
295			x := snap.Exchanges[exchangeID]
296			if x == nil || x.ReceiverID != actor.ID {
297				// 不存在或属于其他接收方/其他身份：统一拒绝。
298				return ErrAccessDenied
299			}
300			if digest != x.Digest {
301				return fmt.Errorf("%w: package digest does not match exchange %q", ErrConflict, exchangeID)
302			}
303			if x.Receipt != nil {
304				if x.Receipt.Outcome != outcome || x.Receipt.Reason != reason {
305					return fmt.Errorf("%w: exchange %q already has a different receipt", ErrConflict, exchangeID)
306				}
307				// 相同回执重交：只是确认已保存的那份回执，没有任何状态变更，
308				// 不落盘——即使本地保存条件当前不可用，也成功返回原确认，
309				// 登记时间保持首次成功登记时的值。
310				conf = ReceiptConfirmation{
311					ExchangeID:   x.ID,
312					Status:       x.Status,
313					Outcome:      x.Receipt.Outcome,
314					RegisteredAt: x.Receipt.RegisteredAt,
315				}
316				return errUnchanged
317			}
318	
319			now := s.now()
320			x.Receipt = &Receipt{Outcome: outcome, Reason: reason, RegisteredAt: now}
321			if outcome == ReceiptAccepted {
322				x.Status = ExchangeAccepted
323			} else {
324				x.Status = ExchangeRejected
325			}
326			s.addAudit(snap, x.PatientID, actor, ActionReceipted, "exchange", x.ID, now)
327			conf = ReceiptConfirmation{
328				ExchangeID:   x.ID,
329				Status:       x.Status,
330				Outcome:      outcome,
331				RegisteredAt: now,
332			}
333			return nil
334		})
335		return conf, err
336	}
337	
338	// GetExchange 供内部使用者按患者查看原包（含固化内容与摘要）及回执。
339	// 患者停用后仍可查看。交换不存在返回 ErrNotFound，属于其他患者返回
340	// ErrMismatchedPatient。
341	func (s *Store) GetExchange(actor Actor, patientID, exchangeID ID) (Exchange, error) {
342		if !actor.valid() || !actor.IsInternal() {
343			return Exchange{}, ErrAccessDenied
344		}
345		var result Exchange
346		err := s.view(func(snap *snapshot) error {
347			x, err := requireExchange(snap, patientID, exchangeID)
348			if err != nil {
349				return err
350			}
351			result = cloneExchangeValue(x)
352			return nil
353		})
354		return result, err
355	}
356	
357	// ListExchanges 供内部使用者按患者查看其全部交换（原包与回执），
358	// 按创建时间旧到新排序；时间戳相同时按交换标识排序。患者停用后仍可查看。
359	func (s *Store) ListExchanges(actor Actor, patientID ID) ([]Exchange, error) {
360		if !actor.valid() || !actor.IsInternal() {
361			return nil, ErrAccessDenied
362		}
363		var result []Exchange
364		err := s.view(func(snap *snapshot) error {
365			if _, err := requirePatient(snap, patientID); err != nil {
366				return err
367			}
368			for _, x := range snap.Exchanges {
369				if x.PatientID == patientID {
370					result = append(result, cloneExchangeValue(x))
371				}
372			}
373			sort.Slice(result, func(i, j int) bool {
374				if !result[i].CreatedAt.Equal(result[j].CreatedAt) {
375					return result[i].CreatedAt.Before(result[j].CreatedAt)
376				}
377				return result[i].ID < result[j].ID
378			})
379			return nil
380		})
381		return result, err
382	}
383	
384	func requireExchange(snap *snapshot, patientID, exchangeID ID) (*Exchange, error) {
385		x := snap.Exchanges[exchangeID]
386		if x == nil {
387			return nil, fmt.Errorf("%w: exchange %q", ErrNotFound, exchangeID)
388		}
389		if x.PatientID != patientID {
390			return nil, fmt.Errorf("%w: exchange %q belongs to patient %q, not %q",
391				ErrMismatchedPatient, exchangeID, x.PatientID, patientID)
392		}
393		return x, nil
394	}
395	
396	func findExchangeByRequest(snap *snapshot, creatorID, requestID string) *Exchange {
397		for _, x := range snap.Exchanges {
398			if x.CreatorID == creatorID && x.RequestID == requestID {
399				return x
400			}
401		}
402		return nil
403	}
404	
405	// sameExchangeRequest 判断重试参数是否与既有交换完全一致（记录集合顺序无关）。
406	func sameExchangeRequest(x *Exchange, patientID ID, receiverID, authorizationID ID, wantedRecordIDs []ID) bool {
407		if x.PatientID != patientID || x.ReceiverID != receiverID || x.AuthorizationID != authorizationID {
408			return false
409		}
410		if len(x.Package.Records) != len(wantedRecordIDs) {
411			return false
412		}
413		// 包内记录按记录标识排序保存，wantedRecordIDs 同样已去重排序。
414		for i, pr := range x.Package.Records {
415			if pr.RecordID != wantedRecordIDs[i] {
416				return false
417			}
418		}
419		return true
420	}
421	
422	func uniqueSortedIDs(ids []ID) []ID {
423		seen := make(map[ID]struct{}, len(ids))
424		out := make([]ID, 0, len(ids))
425		for _, id := range ids {
426			if _, ok := seen[id]; ok {
427				continue
428			}
429			seen[id] = struct{}{}
430			out = append(out, id)
431		}
432		sort.Strings(out)
433		return out
434	}
435	
436	func clonePackage(p Package) Package {
437		p.Records = append([]PackagedRecord(nil), p.Records...)
438		return p
439	}
440	
441	func cloneExchangeValue(x *Exchange) Exchange {
442		y := *x
443		y.Package = clonePackage(x.Package)
444		if x.Receipt != nil {
445			r := *x.Receipt
446			y.Receipt = &r
447		}
448		return y
449	}
450	
451	// canonicalRecord 固定摘要中每个字段的序列化顺序。
452	type canonicalRecord struct {
453		EncounterID ID     `json:"encounter_id"`
454		Category    string `json:"category"`
455		RecordID    ID     `json:"record_id"`
456		VersionID   ID     `json:"version_id"`
457		Version     int    `json:"version"`
458		EffectiveAt string `json:"effective_at"`
459		Content     string `json:"content"`
460	}
461	
462	type canonicalPackage struct {
463		PatientID  ID                `json:"patient_id"`
464		ReceiverID string            `json:"receiver_id"`
465		Records    []canonicalRecord `json:"records"`
466	}
467	
468	// packageDigest 计算包内容的稳定摘要：记录先按标识排序（创建时已排序），
469	// 时间统一为 UTC RFC3339Nano，字段顺序固定，因此与入参顺序无关、可重算核对。
470	func packageDigest(p Package) string {
471		cp := canonicalPackage{
472			PatientID:  p.PatientID,
473			ReceiverID: p.ReceiverID,
474			Records:    make([]canonicalRecord, 0, len(p.Records)),
475		}
476		recs := append([]PackagedRecord(nil), p.Records...)
477		sort.Slice(recs, func(i, j int) bool { return recs[i].RecordID < recs[j].RecordID })
478		for _, r := range recs {
479			cp.Records = append(cp.Records, canonicalRecord{
480				EncounterID: r.EncounterID,
481				Category:    r.Category,
482				RecordID:    r.RecordID,
483				VersionID:   r.VersionID,
484				Version:     r.Version,
485				EffectiveAt: r.EffectiveAt.UTC().Format(time.RFC3339Nano),
486				Content:     r.Content,
487			})
488		}
489		raw, err := json.Marshal(cp)
490		if err != nil {
491			// 参与序列化的都是字符串/整数等基础类型，不应失败。
492			panic(fmt.Errorf("clinical: cannot marshal package digest: %w", err))
493		}
494		sum := sha256.Sum256(raw)
495		return hex.EncodeToString(sum[:])
496	}
