661		// 读取已保存的结果，本身不再落盘）。更正不改写已创建交换的冻结包。
662		if _, err := s.CorrectRecord(doc, recO.ID, 1, "医嘱内容-更正版", "触发一次真实落盘"); err != nil {
663			t.Fatalf("correction that forces persist: %v", err)
664		}
665		again, err := s.CreateExchange(doc, p.ID, rcv.ID, a.ID,
666			[]ID{recD.ID, recO.ID}, "req-reopen-iso")
667		if err != nil {
668			t.Fatalf("retry after persist: %v", err)
669		}
670		assertExchangeMatches(t, again, want, "retry after persist still returns original")
671	
672		if err := s.Close(); err != nil {
673			t.Fatal(err)
674		}
675	
676		s2 := open()
677		t.Cleanup(func() { _ = s2.Close() })
678	
679		got, err := s2.GetExchange(doc, p.ID, x.ID)
680		if err != nil {
681			t.Fatalf("get after reopen: %v", err)
682		}
683		assertExchangeMatches(t, got, want, "exchange after reopen")
684	
685		gotList, err := s2.ListExchanges(doc, p.ID)
686		if err != nil {
687			t.Fatal(err)
688		}
689		if len(gotList) != 1 {
690			t.Fatalf("list after reopen len = %d, want 1", len(gotList))
691		}
692		assertExchangeMatches(t, gotList[0], want, "list after reopen")
693	
694		acts := auditActions(mustAudit(t, s2, p.ID))
695		if acts[ActionExchanged] != 1 {
696			t.Fatalf("exchange_created audits after reopen = %d, want 1", acts[ActionExchanged])
697		}
698		if acts[ActionReceipted] != 0 {
